from pathlib import Path
from PIL import Image,ImageDraw,ImageFilter
import json,hashlib,numpy as np
from pypdf import PdfReader
R=Path.cwd();K=R/'Kids Highland Cow';A=K/'info/assets';O=R/'tmp/kids-highland-cow'
manifest=json.loads((O/'source-manifest.json').read_text())
for item in manifest:assert hashlib.sha256((R/item['new']).read_bytes()).hexdigest()==item['sha256']
for p in [A/'reference-master.png',*[A/f'stage-{s:02}.png' for s in range(1,7)]]:
 im=Image.open(p);assert im.size==(2400,3000);assert all(abs(n-300)<.1 for n in im.info['dpi'])
# Compare the transfer to the original ink after the common uniform mapping.
o=Image.open(O/'outline-transparent.png');src=Image.open(A/'source-ink.png').convert('L').resize((2400,2978),Image.Resampling.LANCZOS);p=Image.new('L',(2400,3000),255);p.paste(src,(0,11));near=np.asarray(Image.eval(p,lambda x:255-x).filter(ImageFilter.MaxFilter(35)))>0;transfer=np.asarray(o)[:,:,3]>128
ratio=float(near[transfer].mean());assert ratio>.99,ratio
check={'sourceHashesUnchanged':True,'allMasterStagePixels':[2400,3000],'dpi':300,'transferPixelsNearCanonicalSourceInk':ratio,'sharedUniformSourceTransform':True,'stage6EqualsReference':hashlib.sha256((A/'stage-06.png').read_bytes()).hexdigest()==hashlib.sha256((A/'reference-master.png').read_bytes()).hexdigest()}
for kind,size in [('painting-guide',(612,792)),('finished-reference',(576,720))]:
 pdf=PdfReader(O/f'kids-highland-cow-{kind}-8x10.pdf');assert len(pdf.pages)==1;assert tuple(float(v) for v in (pdf.pages[0].mediabox.width,pdf.pages[0].mediabox.height))==size
check['onePagePDFSizes']={'guide':[612,792],'reference':[576,720]}
pdf=PdfReader(O/'kids-highland-cow-painting-guide-8x10.pdf');t=pdf.pages[0].extract_text();(O/'guide-text.txt').write_text(t);assert 'No mixing needed.' in t
sheet=Image.new('RGB',(1200,580),'#F1EDE7');d=ImageDraw.Draw(sheet)
for s in range(1,7):
 im=Image.open(A/f'stage-{s:02}.png');im.thumbnail((185,232));x=8+(s-1)%6*200;sheet.paste(im,(x,30));d.text((x,8),f'Step {s}',fill='black')
# Geometry overlay and close detail are scratch review artifacts.
sheet.save(O/'stage-contact.png');ref=Image.open(A/'reference-master.png');ref.crop((420,1050,1740,2220)).resize((1000,886),Image.Resampling.LANCZOS).save(O/'face-detail.png')
ref.convert('RGBA').save(O/'registration-reference.png');Image.alpha_composite(ref.convert('RGBA'),o).resize((800,1000),Image.Resampling.LANCZOS).save(O/'geometry-overlay.png')
(O/'verification.json').write_text(json.dumps(check,indent=2))
readme='''# Kids Highland Cow\n\nAges 8-14. Six illustrated steps, two columns by three rows. Seven ready-to-use paints: light blue, caramel tan, cream, pink, brown, black and white. No mixing. The target follows the supplied portrait cow bust with a pink bow and blue background. Its original crop at the left and bottom is preserved; the source is uniformly scaled, without stretching.\n\n## Production files\n\n- `../kids-highland-cow-outline-8x10.svg`: transparent true vector transfer, black #000000, rounded 3-point strokes, 8 x 10 inches. Black pupils become paintable boundaries with white-shine outlines.\n- `../kids-highland-cow-painting-guide-8x10.pdf`: one US Letter page.\n- `../kids-highland-cow-finished-reference-8x10.pdf`: one 8 x 10 page, losslessly embedding the 2400 x 3000, 300-DPI color master.\n- `../assets/`: lossless guide-image extraction, including the full drying panel.\n\n## Sources and edit assets\n\nThe three supplied files are unchanged under `archive/previous-root-files/`. The black-and-white PNG controls the line geometry; its Illustrator companion is also preserved. The color PNG supplies the palette, body/background distinction where the cropped bust is open, and inner-ear color placement. The resulting target is a clean flat-color adaptation, with the supplied linework retained, rather than the original shaded raster.\n\n'''
for item in manifest:readme+='- `'+Path(item['new']).name+'`: SHA-256 `'+item['sha256']+'`.\n'
readme+='''\n`assets/geometry.json` saves the smoothed source centerlines, pupil boundaries and uniform placement. `assets/paint-layers.json` saves the matching filled color regions and source ink paths. `paint-regions.npy`, `pupil-mask.npy` and `source-ink.png` support intentional mask edits. `reference-master.svg`, `reference-master.png` and `stage-01.png` through `stage-06.png` are the shared reference/stage masters. Stages 5 and 6 show the same finished painting; the guide uses a separate flat tabletop scene for step 6. `page-logo.png` preserves the complete shared logo and alpha, recolored in warm browns and cream.\n\n`src/build.cjs` rebuilds from the saved canonical geometry and paint layers. `src/guide-pdf.cjs` is the editable layout. The shared guide plan is the `kids-highland-cow` entry in `assets/tools/guide-template/kits.json`. `prepare.py`, `trace.py`, `vector.cjs`, `outline.cjs`, `paint.py` and `paint-vector.cjs` are the deliberate source-reconstruction pipeline; normal rebuilds do not re-trace or reclassify the artwork.\n\nRun from the project root:\n\n```powershell\nnode "Kids Highland Cow/info/src/build.cjs"\n# Inspect the outline, reference, guide and stages in tmp/kids-highland-cow/.\nnode "Kids Highland Cow/info/src/build.cjs" --promote\nnode Tools/guide-image-extractor.cjs "Kids Highland Cow/kids-highland-cow-painting-guide-8x10.pdf"\n```\n\nUse `--retrace` only for an intentional geometry/mask revision; it rebuilds source region labels, centerlines and color layers before the normal build. Scratch exports and checks stay in `tmp/kids-highland-cow/`.\n\n## Review\n\nVisually reviewed the transparent transfer on white, finished reference, middle stage, six-stage contact sheet, enlarged face, geometry overlay and rendered guide. Checked black 3-point vector-only transfer styling, transparent interiors/margins, source registration, cumulative color order, matching final-stage/reference pixels, 2400 x 3000 masters at 300 DPI, single-page Letter/8 x 10 PDF sizes, legible captions, full logo, paint names, no mixing, and the exact finished reference in the flat drying scene. Supplied source hashes were checked after relocation. The original raster ink and masks were traced into smooth vector paint layers before print rendering; no new raster detail is claimed. Print artwork at Actual size / 100%. Digital file checks only.\n'''
(K/'info/README.md').write_text(readme)
print(json.dumps(check,indent=2))
